Btn.MouseButton1Click:Connect(function()
    Btn.Text = "⏳ ĐANG NẠP..."
    Status.Text = "Vui lòng chờ..."
    task.spawn(function()
        local ok, err = pcall(function()
            decode_and_run(b64)
        end)
        
        if ok then
            Status.Text = "✅ THÀNH CÔNG!"
            task.wait(0.5)
            ScreenGui:Destroy()
        else
            Status.Text = "❌ LỖI GIẢI NÉN!"
            Btn.Text = "🔄 THỬ LẠI"
            warn("Lỗi: " .. tostring(err))
        end
    end)
end)
